type Answer = {
  status: "answered" | "insufficient_evidence";
  citations: string[];
};

export function checkEvidence(answer: Answer, allowed: Set<string>) {
  const citationsAllowed = answer.citations.every(id => allowed.has(id));
  const outcomeConsistent = answer.status === "answered"
    ? answer.citations.length > 0
    : answer.citations.length === 0;
  return { citationsAllowed, outcomeConsistent };
}

import { z } from "zod";

const RoutingProposal = z.object({
  schemaVersion: z.literal(1),
  outcome: z.enum(["route", "needs_clarification"]),
  department: z.enum(["billing", "technical", "sales"]).nullable(),
  reason: z.string().min(1).max(400),
}).strict().superRefine((value, context) => {
  const hasDepartment = value.department !== null;
  if ((value.outcome === "route") !== hasDepartment) {
    context.addIssue({
      code: "custom",
      message: "Only routing outcomes may select a department.",
    });
  }
});

export function parseProposal(value: unknown) {
  return RoutingProposal.safeParse(value);
}

type GenerationRun = {
  id: string;
  conversationId: string;
  userMessageId: string;
  assistantMessageId: string;
  status: "submitted" | "streaming" | "completed" | "cancelled" | "failed";
  partialText: string;
  lastSequence: number;
  errorCode: "timeout" | "provider_error" | "connection_lost" | null;
};
